SET verification_sent = true
WHERE id = '{{ $('Get staff and managers').item.json.outage_log_id }}';

parameters.jsCode:
const items = $input.all();
const result = [];

function getKyivDateString(date) {
  const formatter = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Kyiv', year: 'numeric', month: '2-digit', day: '2-digit' });
  return formatter.format(date);
}

function getKyivDayName(date) {
  const formatter = new Intl.DateTimeFormat('en-US', { timeZone: 'Europe/Kyiv', weekday: 'short' });
  return formatter.format(date).toLowerCase();
}

function getKyivOffsetMinutes(dateStr) {
  const formatter = new Intl.DateTimeFormat('en', { timeZone: 'Europe/Kyiv', timeZoneName: 'longOffset' });
  const parts = formatter.formatToParts(new Date(`${dateStr}T12:00:00Z`));
  const tzName = parts.find(p => p.type === 'timeZoneName')?.value ?? 'GMT+02:00';
  const match  = tzName.match(/GMT([+-])(\d{2}):(\d{2})/);
  if (!match) return 120;
  return (match[1] === '+' ? 1 : -1) * (parseInt(match[2]) * 60 + parseInt(match[3]));
}

function toUtcDate(dateStr, timeStr) {
  const offsetMins = getKyivOffsetMinutes(dateStr);
  const [h, m] = timeStr.split(':').map(Number);
  const minutesUtc = (h * 60 + m) - offsetMins;
  const res = new Date(`${dateStr}T00:00:00Z`);
  res.setUTCMinutes(res.getUTCMinutes() + minutesUtc);
  return res;
}

function formatKyivTime(date) {
  const formatter = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Kyiv', hour: '2-digit', minute: '2-digit' });
  return formatter.format(date);
}

for (const item of items) {
  const data = item.json;
  const outageStart = new Date(data.planned_start);
  const outageEnd = new Date(data.planned_end);
  const workingHours = data.working_hours;

  // Since Daily Verification only takes outages that started TODAY (Kyiv), we just check today's schedule
  const currentStr = getKyivDateString(outageStart);
  const dayName = getKyivDayName(outageStart);

  const schedule = workingHours[dayName];
  if (schedule && schedule.isOpen) {
    const workOpen = toUtcDate(currentStr, schedule.start);
    let workClose = toUtcDate(currentStr, schedule.end);

    if (workClose <= workOpen && schedule.end === '00:00') {
      workClose = new Date(workClose.getTime() + 24 * 60 * 60 * 1000);
    }

    const segStart = new Date(Math.max(outageStart.getTime(), workOpen.getTime()));
    const segEnd = new Date(Math.min(outageEnd.getTime(), workClose.getTime()));

    if (segStart < segEnd) {
      // It intersects! Adjust the string times.
      data.start_time = formatKyivTime(segStart);
      data.end_time = formatKyivTime(segEnd);

      // Clean up extra fields to keep JSON clean
      delete data.working_hours;
      delete data.planned_start;
      delete data.planned_end;

      result.push({ json: data });
    }
  }
}

return result;
